window.DICTIONARY_ENTRY_SHARDS["00f6-006b"]={"00f6-006b:8fe7e74c81129e":{"word":"Ökologie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·lo·gie","de-DE":"Öko·lo·gie"},"forms":[{"form":"Ökol.","tags":["Kurzform"]},{"form":"Ökologie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Teilgebiet der Biologie, welches sich mit den Wechselbeziehungen zwischen Organismen und ihrer natürlichen Umwelt beschäftigt"}],"synonyms":["Bioökologie"],"origins":["Neubildung des 19. Jahrhunderts auf der Grundlage von griechisch οἶκος (oikos^☆) ^(→ grc) „Haus, Haushalt“ und λόγος (logos^☆) ^(→ grc) „Lehre“ bzw. -logie"],"examples":[{"text":"„Unter Oecologie [Anm. Wiktionary: Heutige Schreibweise ist Ökologie.] verstehen wir die gesammte Wissenschaft von den Beziehungen des Organismus zur umgebenden Aussenwelt, wohin wir im weiteren Sinne alle „Existenz-Bedingungen“ rechnen können. Diese sind theils organischer, theils anorganischer Natur; sowohl diese als jene sind, wie wir vorher gezeigt haben, von der grössten Bedeutung für die Form der Organismen, weil sie dieselbe zwingen, sich ihnen anzupassen.“","reference":"Ernst Haeckel:Generelle Morphologie der Organismen. Allgemeine Grundzüge der organischen Formen-Wissenschaft, mechanisch begründet durch die von Charles Darwin reformirte Descendenz-Theorie, 1866."},{"text":"„Geprägt wurde der Begriff Ökologie von HAECKEL (1866, S. 286) als „die gesamte Wissenschaft von den Beziehungen des Organismus zur umgebenden Außenwelt“. Bereits drei Jahre später erweiterte derselbe Autor (HAECKEL 1869, S. 49) den Begriff zur „Lehre von der Ökonomie, von dem Haushalt und den tierischen Organismen“, wobei Fragen der Stoff- und Energieumwandlungen und -transporte (Stoffkreislauf, Energiefluss) in den Lebensgemeinschaften (Biozönose) mit eingeschlossen wurden.“","reference":"Haeckelzitat „Ökologie“ 1869 nach: W. Kuttler: Handbuch zur Ökologie. 2. Aufl. Berlin 1995. In: G. W. Wittkämper (Westfälische Wilhelmsuniversität Münster): Umweltpolitik: Grundbegriffe, Umweltprozesse, Umweltfunktionen."},{"text":"„Ökologie ist die wissenschaftliche Untersuchung der Wechselwirkungen, die die Verteilung und Häufigkeit von Organismen bestimmen.“","reference":"Aus: Charles Krebs, 1972, Ecology. In: Lexikon der Biologie, Artikel „Ökologie“. spektrum.de, abgerufen am 16. April 2023."},{"text":"„Ökologie ist die Wissenschaft vom Stoff- und Energiehaushalt der Biosphäre und ihrer Untereinheiten (zum Beispiel Ökosysteme) sowie von den Wechselbeziehungen zwischen den verschiedenen Organismen, zwischen Organismen und den auf sie wirkenden Umweltfaktoren sowie zwischen den einzelnen unbelebten Umweltfaktoren.“","reference":"Hartmut Bick: Grundzüge der Ökologie. 3. Auflage, Gustav Fischer, Stuttgart 1998; S. 8. ISBN 3-437-25910-5."},{"text":"„Die Ökologie lässt sich auf drei wesentliche Fachbereiche reduzieren. Man unterscheidet zwischen der Synökologie, der Autökologie und der Demökologie.“","reference":"Ökologie. In: Lexikon der Nachhaltigkeit. nachhaltigkeit.info (Aachener Stiftung Kathy Beys), abgerufen am 16. April 2023."}],"idioms":[],"collocations":[],"derivations":["ökologisch","Öko","Ökologe","Ökotonne","Ökosystem"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökologie","id":"8fe7e74c81129e"},"00f6-006b:6003b534a7dfa5":{"word":"Ökol.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"Öko·l.","de-DE":"Öko·l."},"forms":[],"senses":[{"definition":"Ökologie"}],"synonyms":[],"origins":[],"examples":[{"text":"Ich habe Ökol. studiert.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökol.","id":"6003b534a7dfa5"},"00f6-006b:27ca921d03a8b9":{"word":"Ökonomie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·no·mie","de-DE":"Öko·no·mie"},"forms":[{"form":"Ök.","tags":["Kurzform"]},{"form":"Ökon.","tags":["Kurzform"]},{"form":"Ökonomie","tags":["Nominativ","Singular"]},{"form":"Ökonomien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Struktur der Wirtschaft eines Gebietes"},{"definition":"sparsamer Gebrauch/Umgang von/mit etwas"},{"definition":"Wirtschaftswissenschaft"},{"definition":"ein Landwirtschaftsbetrieb"}],"synonyms":["Volkswirtschaft","Wirtschaft","Wirtschaftsraum","Wirtschaftswissenschaft","Wirtschaftswissenschaften","Ökonomik"],"origins":["abgeleitet vom griechischen oikonomia „Haushaltung, Verwaltung“"],"examples":[{"text":"Die Ökonomie dieses Landes wächst langsam.","reference":""},{"text":"„Fast alle Besucher prangerten die Doppelmoral der Amerikaner an, die stolz ihre Gleichheitsprinzipien präsentierten, deren Ökonomie in den Südstaaten aber zum größten Teil auf Sklavenarbeit basierte.“","reference":"Geert Mak: Amerika!. Auf der Suche nach dem Land der unbegrenzten Möglichkeiten. Siedler, München 2013, ISBN 978-3-88680-0023-6 , Seite 174."},{"text":"„Immerhin hat sogar die Politik die Notwendigkeit eines ökologisch gesunden Rheins erkannt, nachdem jahrzehntelang nur Ökonomie und Wirtschaftswachstum im Vordergrund standen.“","reference":"Bruno P. Kremer: Der Rhein von den Alpen bis zur Nordsee. Fachtechnik + Mercator-Verlag, Duisburg 2010, ISBN 978-3-87463-456-4, Seite 29."},{"text":"Neben einem deutlichen nostalgischen Aspekt spielen dabei die Ökonomie der Mittel und das Ideal der „Ehrlichkeit“ dieser Mittel eine Rolle.","reference":"Wikipedia-Artikel „Pixel-Art“"},{"text":"Die Ökonomie untersucht wirtschaftliche Vorgänge.","reference":""},{"text":"Araber werden zu leichten Diensten in der Ökonomie verwendet.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 26. Dezember 2015."}],"idioms":[],"collocations":[],"derivations":["Ökonom","Ökonometrie","Ökonomierat","Ökonomik","ökonomisch","ökonomisieren","Ökonomismus","Ökonomist"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökonomie","id":"27ca921d03a8b9"},"00f6-006b:7e5e22e65ecfc0":{"word":"ökon.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"öko·n.","de-DE":"öko·n."},"forms":[{"form":"ök.","tags":["alternative"]}],"senses":[{"definition":"ökonomisch"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ökon.","id":"7e5e22e65ecfc0"},"00f6-006b:cb9f05a9d2ae89":{"word":"ökum.","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"ökum.","de-DE":"ökum."},"forms":[],"senses":[{"definition":"ökumenisch"}],"synonyms":[],"origins":[],"examples":[{"text":"„[Siegmund-Schultze, Friedrich] – Pionier der ökum. Bewegung und aktive Mitarbeit in verschiedenen ökum. Organisationen seit 1908, Teiln. der WPC Oxford 1937 und der WGK Edinburgh 1937, Gründer und Geschäftsführer des Ökum. Archivs Soest/Westfalen 1958–1968.“","reference":"Nora Andrea Schulze: Verantwortung für die Kirche. Stenographische Aufzeichnungen und Mitschriften von Landesbischof Hans Meiser, 1933–1955. Band 3: 1937, Vandenhoeck & Ruprecht, Göttingen 1985, ISBN 9783525557655, Seite 1082 , „Personenregister/Biographische Angaben“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ökum.","id":"cb9f05a9d2ae89"},"00f6-006b:c3416a655c0669":{"word":"Ökosystem","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Öko·sys·tem","de-DE":"Öko·sys·tem"},"forms":[{"form":"Ökosystem","tags":["Nominativ","Singular"]},{"form":"Ökosysteme","tags":["Nominativ","Plural"]},{"form":"Ökosystems","tags":["Genitiv","Singular"]},{"form":"Ökosystemen","tags":["Dativ","Plural"]}],"senses":[{"definition":"ein Bereich, ein Teil einer Landschaft, in dem Lebewesen, die aufeinander angewiesen sind, zusammen existieren"}],"synonyms":["Mutter Natur","Natur","Umwelt"],"origins":["Determinativkompositum aus dem gebundenen Lexem Öko- (von altgriechisch οἶκος (oikos^☆) ^(→ grc) „Haus, Hof, Hauswirtschaft“) und dem Substantiv System","Der Begriff wurde vom deutschen Biologen Richard Woltereck 1928 erstmals als „ökologisches System“ eingeführt, was vom britischen Botaniker Arthur Georg Transley 1935 als ecosystem ^(→ en) ins Englische übersetzt wurde. Aus der englischsprachigen Literatur wurde der Begriff als Ökosystem wieder ins Deutsche übernommen."],"examples":[{"text":"Ein See ist ein gutes Beispiel für ein Ökosystem.","reference":""},{"text":"„Für Wasserkraftwerke werden Stauseen errichtet, die riesige Ökosysteme zerstören, und für Energiesparlampen muss in China hochgiftiges Quecksilber abgebaut werden.“","reference":"Vince Ebert: Machen Sie sich frei!. Sonst tut es keiner für Sie. Rowohlt Taschenbuch Verlag, Reinbek 2011, ISBN 978-3-499-62651-7, Seite 158."},{"text":"„Andererseits warnen Umweltschützer vor der Zerstörung kaum erforschter Ökosysteme, wenn man den Meeresgrund quadratkilometerweise durchpflügt.“","reference":"Jens Glüsing u.a.: Raubbau für die Rettung des Planeten. In: Spiegel Online. 29. Oktober 2021, ISSN 0038-7452 (Bezahlschranke, URL, abgerufen am 10. April 2023) ."},{"text":"„Die Blütenpflanzen beeinflussen außerdem das Klima, gestalten unsere Ökosysteme und haben sogar zur Entstehung zahlreicher neuer Insekten, Pilze und Vögel beigetragen.“","reference":"Anna Manz: Neuer Stammbaum für die Blütenpflanzen. In: scinexx.de. 25. April 2024, abgerufen am 11. August 2024."},{"text":"„Es gehe dabei nicht um recyclebare Baumaterialien, sondern eher darum, wie das Hochhaus das Ökosystem der ganzen Gegend verändere.“","reference":"Jón Atli Jónasson: Schmerz. Ein Fall für Dora und Rado. 2. Auflage. Scherz, Frankfurt/Main 2024 (übersetzt von Freyja Melsted), ISBN 978-3-651-00134-3, Seite 288. Isländisches Original Reykjavík 2022."}],"idioms":[],"collocations":[],"derivations":["ökosystemisch","ökosystemar"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökosystem","id":"c3416a655c0669"},"00f6-006b:8e184365a59466":{"word":"Ökonometrie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·no·me·trie","de-DE":"Öko·no·me·trie"},"forms":[{"form":"Ökonometrie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Teilgebiet der Wirtschaftswissenschaften, welches die ökonomische Theorie sowie mathematische Methoden und statistische Daten zusammenführt, um wirtschaftstheoretische Modelle empirisch zu überprüfen und ökonomische Phänomene quantitativ zu analysieren"}],"synonyms":[],"origins":[],"examples":[{"text":"Ziel der Ökonometrie ist es, funktionale Beziehungen zwischen ökonomischen Variablen aufzuspüren und zu messen.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 26. Dezember 2015."}],"idioms":[],"collocations":[],"derivations":["ökonometrisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökonometrie","id":"8e184365a59466"},"00f6-006b:f1834f98b6965d":{"word":"Ökonym","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ök·o·nym","de-DE":"Ök·o·nym"},"forms":[{"form":"Ökonym","tags":["Nominativ","Singular"]},{"form":"Ökonyme","tags":["Nominativ","Plural"]},{"form":"Ökonyms","tags":["Genitiv","Singular"]},{"form":"Ökonymen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Sammelbezeichnung für kommerzielle Ergonyme, also für Waren- und Dienstleistungsbezeichnungen"}],"synonyms":[],"origins":["Griechisch \"oikonomía\" \"Einrichtung, Ordnung, Verwaltung\" + \"ónoma\" \"der Name\"","Der Begriff wurde von Christoph Platen 1997 vorgeschlagen."],"examples":[{"text":"Drei jedem deutschen Konsumenten bekannte Ökonyme sind Tempo, Milka und Jägermeister.","reference":""},{"text":"„Grundsätzlich kann gesagt werden, dass der Begriff Ökonym – aufgrund seiner Möglichkeit des internationalen Gebrauchs – besser geeignet wäre als der Terminus Warenname.“","reference":"Michael Fink: Waren- und Produktnamen als besondere Namenskategorie, 2010, S. 23. Warenname: kursiv gedruckt."},{"text":"„Gleich zu Beginn verriet uns der Vortragende, Prof. em. Dr. Helmut Liebsch, dass Ökonyme sich von Ökonomie (Wirtschaft/Waren) und Onyma (Name) herleite, was unschwer zu erkennen sei, aber die Benennung selber in der Onomastik (der Namenkunde) relativ selten vorkomme.“","reference":"Bericht über einen Vortrag in: Der Sprachdienst 54, 2, 2010, S. 73."}],"idioms":[],"collocations":[],"derivations":["Ökonymie"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökonym","id":"f1834f98b6965d"},"00f6-006b:e13530c3abbea9":{"word":"ökologisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"öko·lo·gisch","de-DE":"öko·lo·gisch"},"forms":[{"form":"ökologisch","tags":["Positiv"]},{"form":"ökologische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ökologischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ökologischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ökologischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ökologisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ökologisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ökologisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ökologisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ökologisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die Ökologie betreffend"},{"definition":"in Einklang mit der Natur, der Umwelt"}],"synonyms":["biologisch"],"origins":["Ableitung vom Stamm des Wortes Ökologie mit dem Derivatem (Ableitungsmorphem) -isch, belegt seit Ende des 19. Jahrhunderts"],"examples":[{"text":"„Die 14 Hektar große Grünzone hat heute neben der städtebaulichen auch wichtige wasserwirtschaftliche und ökologische Funktionen.“","reference":"Wikipedia-Artikel „Flughafen (Nürnberg)“ (Stabilversion)"},{"text":"Die ökologische Landwirtschaft ist wichtig für die Umwelt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"ökologisch","id":"e13530c3abbea9"},"00f6-006b:7d0ba80fe3444e":{"word":"ökonomisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"öko·no·misch","de-DE":"öko·no·misch"},"forms":[{"form":"ök.","tags":["Kurzform"]},{"form":"ökon.","tags":["Kurzform"]},{"form":"ökonomisch","tags":["Positiv"]},{"form":"ökonomische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ökonomischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ökonomischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ökonomischer","tags":["Komparativ"]},{"form":"ökonomisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"ökonomischere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"ökonomischste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"ökonomischerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"ökonomischeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"ökonomischerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"ökonomischeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"ökonomischstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"ökonomischsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"ökonomischster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"ökonomischstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am ökonomischsten","tags":["Superlativ"]},{"form":"er ist ökonomisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ökonomisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ökonomisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist ökonomischer","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist ökonomischer","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind ökonomisch","tags":["Positiv","predicative","Plural"]},{"form":"sie ist ökonomischer","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind ökonomischer","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am ökonomischsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am ökonomischsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am ökonomischsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am ökonomischsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"wirtschaftlich gesehen, die Wirtschaft betreffend"},{"definition":"mit möglichst wenig Aufwand"}],"synonyms":["gewerblich","gewinnorientiert","Handels...","kaufmännisch","kommerziell","merkantil","privatwirtschaftlich","profitorientiert","unternehmerisch","wirtschaftlich"],"origins":[],"examples":[{"text":"Die ökonomische Entwicklung gibt derzeit zu Sorgen Anlass.","reference":""},{"text":"„Doch je mehr Geld, Sklaven und Güter aller Art aus den eroberten Gebieten nach Rom strömten, desto entscheidender veränderte sich das ökonomische und soziale Gleichgewichte in der agrarisch geprägten Stadt.“","reference":"Pedro Barceló: Kleine römische Geschichte. Sonderausgabe, 2., bibliographisch aktualisierte Auflage. Primus Verlag, Darmstadt 2012, ISBN 978-3534250967 , Seite 45."},{"text":"Wir müssen mit unseren Ausgaben so ökonomisch wie möglich verfahren.","reference":""},{"text":"„Das Genitivattribut erlaubt auf sehr ökonomische Weise Präzisierungen von Nominalgruppen.“","reference":"Matthias Granzow-Emden: Deutsche Grammatik verstehen und unterrichten. Narr Verlag, Tübingen 2013, ISBN 979-3-8233-6656-0, Seite 224"}],"idioms":[],"collocations":[],"derivations":["Ökonomik","ökonomisieren","Ökonomismus"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"ökonomisch","id":"7d0ba80fe3444e"},"00f6-006b:6183855f4ddc77":{"word":"Ökologe","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·lo·ge","de-DE":"Öko·lo·ge"},"forms":[{"form":"Ökologe","tags":["Nominativ","Singular"]},{"form":"Ökologen","tags":["Nominativ","Plural"]},{"form":"Ökologin","tags":["feminine"]}],"senses":[{"definition":"eine Person, die sich in großem Ausmaß mit dem Fachgebiet der Ökologie beschäftigt"}],"synonyms":[],"origins":[],"examples":[{"text":"Einige Ökologen vermuten, dass es kein Zurück mehr gibt, wenn die Waldfläche zur Hälfte zerstört ist, andere setzen die Grenze bei 30 bis 40 Prozent Verlust an.","reference":"Daniel Lingenhöhl: Regenwald auf dem Trockenen. Ökologie. In: Zeit Online. 19. Mai 2009, ISSN 0044-2070 (URL, abgerufen am 9. Februar 2013) ."},{"text":"„In einer anderen Studie interessierten sich Ökologen aus Georgia für die Verbreitung der sogenannten Indianerbanane in Amerika.“","reference":"Johann Grolle: Verwaiste Gärten. In: SPIEGEL GESCHICHTE. Nummer 1: Die ersten Amerikaner, 2023 , Seite 48-56, Zitat Seite 54."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökologe","id":"6183855f4ddc77"},"00f6-006b:91dcc64eb27898":{"word":"Ökonom","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·nom","de-DE":"Öko·nom"},"forms":[{"form":"Ökonom","tags":["Nominativ","Singular"]},{"form":"Ökonomen","tags":["Nominativ","Plural"]},{"form":"Ökonomin","tags":["feminine"]}],"senses":[{"definition":"Fachmann der Wirtschaftswissenschaften"},{"definition":"Besitzer eines landwirtschaftlichen Betriebs, Verwalter"}],"synonyms":["Volkswirtschaftler","Wirtschafter","Wirtschaftswissenschaftler"],"origins":["belegt seit Anfang des 17. Jahrhunderts, entlehnt von lateinisch oeconomus ^(→ la), das auf griechisch οἰκο-νόμος (oiko-nomos^☆) ^(→ grc) „Haushalter, Verwalter, Wirtschafter“ zurückgeht"],"examples":[{"text":"Der Ökonom, der seit 15 Jahren an der Universität Zürich lehrt und 2008 mit dem «Schweizer Nobelpreis» Marcel-Benoist-Preis ausgezeichnet wurde, erforscht Fairness und Kooperation beim wirtschaftlichen Entscheidungsverhalten des Menschen.","reference":"Schweizer Ökonom auf Nobelpreis-Kurs (Basler Zeitung, 26.09.2009)"},{"text":"„Vor einigen Jahren befragte der Ökonom Kip Viscusi eine Gruppe von Kettenrauchern, wie viele Lebensjahre sie das Rauchen kosten würde.“","reference":"Vince Ebert: Machen Sie sich frei!. Sonst tut es keiner für Sie. Rowohlt Taschenbuch Verlag, Reinbek 2011, ISBN 978-3-499-62651-7, Seite 44."},{"text":"„List aber, der wahrscheinlich wichtigste Ökonom Deutschlands, interessierte sich nur für die Realität und war trotzdem Utopist.“","reference":"Eric T. Hansen mit Astrid Ule: Die ängstliche Supermacht. Warum Deutschland endlich erwachsen werden muss. Lübbe, Köln 2013, ISBN 978-3-431-03874-3, Seite 26."},{"text":"„Und zu versuchen, eine Antwort auf die Frage zu finden, die sich die meisten Wirtschaftswissenschftler auf der ganzen Welt stellen, nur deutsche Ökonomen nicht: Wie kann der Kapitalismus zum Wohle aller verbessert werden?“","reference":"Eric T. Hansen mit Astrid Ule: Die ängstliche Supermacht. Warum Deutschland endlich erwachsen werden muss. Lübbe, Köln 2013, ISBN 978-3-431-03874-3, Seite 171."},{"text":"„Die meisten Ökonomen halten es für völlig unproblematisch, Klimaschutz zu betreiben.“","reference":"Ulrike Herrmann: Das Ende des Kapitalismus. 1. Auflage. Kiepenheuer & Witsch, Köln 2022, ISBN 9783462002553, Seite 216"},{"text":"Die örtlichen Ökonomen und Winzer waren mit dem Vorschlag des Stadtrats nicht einverstanden.","reference":""}],"idioms":[],"collocations":[],"derivations":["ökonometrisch","ökonomisch","Ökonometriker","Ökonomie","Ökonomik","Ökonomiker"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökonom","id":"91dcc64eb27898"},"00f6-006b:8dc68ba32c0c7e":{"word":"Ökowein","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·wein","de-DE":"Öko·wein"},"forms":[{"form":"Ökowein","tags":["Nominativ","Singular"]},{"form":"Ökoweine","tags":["Nominativ","Plural"]},{"form":"Ökoweins","tags":["Genitiv","Singular"]},{"form":"Ökoweinen","tags":["Dativ","Plural"]},{"form":"Ökoweines","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Weine, die nach Prinzipien des ökologischen Anbaus hergestellt wurden"}],"synonyms":[],"origins":["Determinativkompositum aus dem gebundenen Lexem Öko- (von altgriechisch oikos „Haus, Hof, Hauswirtschaft“) und dem Substantiv Wein"],"examples":[{"text":"Ökoweine liegen zur Zeit voll im Trend.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökowein","id":"8dc68ba32c0c7e"},"00f6-006b:614ef0686591f3":{"word":"Ökostrom","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·strom","de-DE":"Öko·strom"},"forms":[{"form":"Ökostrom","tags":["Nominativ","Singular"]},{"form":"Ökostrome","tags":["Dativ","Singular"]},{"form":"Ökostroms","tags":["Genitiv","Singular"]},{"form":"Ökostromes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"elektrische Energie, die aus erneuerbaren Energiequellen gewonnen wird"}],"synonyms":["alternative Energie","Alternativenergie","erneuerbare Energie","grüner Strom","Grünstrom","Naturenergie","Naturstrom","regenerative Energie"],"origins":[],"examples":[{"text":"„Bei der Produktion von Ökostrom wird weltweit am stärksten auf Windenergie gesetzt.“","reference":"Yvonne Maier: Windparks – Wenn Ökostrom die Nahrungsnetze durcheinander bringt. In: Bayerischer Rundfunk. 28. November 2018 (URL, abgerufen am 17. September 2021) ."},{"text":"„Wie kann ich meinen Betrieb auf Ökostrom umstellen?“","reference":"Volker Witting: Weinbau – Winzer setzen auf Klimaschutz und Nachhaltigkeit. In: Deutsche Welle. 16. Juli 2021 (URL, abgerufen am 17. September 2021) ."},{"text":"Wenn Sie Ökostrom beziehen wollen, achten Sie auf Ökostromlabel wie dem 'ok-power-label' oder dem 'Grüner Strom Label'.","reference":""},{"text":"„Erneuerbare Energien (gef. gem. EEG)“ bedeutet lediglich: Hier zahlen sie als Kunde für den von Ihnen bezogenen Strom die EEG-Abgabe, eine Abgabe nach dem 'Erneuerbaren Energie Gesetz (EEG)'. Dieses Kriterium sagt nichts über die Herkunft des Stromes aus. Dieser Strom wird also auch in Kohle- und Gaskraften oder Atommeilern produziert und ist garantiert kein Ökostrom.","reference":""},{"text":"„Was kommt aus der Steckdose, wenn man bei seinem Stromanbieter extra zahlt für «Ökostrom»? Auf jeden Fall kein reiner Ökostrom.“","reference":"Muriel Jeisy: Aus der Steckdose kommt kein reiner Ökostrom. In: Schweizer Radio und Fernsehen. 11. September 2015 (URL, abgerufen am 17. September 2021) ."},{"text":"„Am besten fürs Klima ist es, wenn die Wärmepumpe mit Ökostrom betrieben wird.“","reference":"Stefanie Peyk: Klimaschutz – Heizen mit Erdwärme. In: Südwestrundfunk. 5. August 2022 (URL, abgerufen am 16. August 2022) ."},{"text":"„Privathaushalte erzeugen selbst Ökostrom und handeln diesen untereinander, etwa so, wie man Eier vom Bauern nebenan holt. Das soll den Umstieg auf erneuerbare Energien attraktiver machen. Ein Modellprojekt startet jetzt im Allgäu.“","reference":"\"Pebbles\" – Modellprojekt für lokalen Strommarkt startet in Wildpoldsried. In: Bayerischer Rundfunk. 23. Oktober 2020 (Text und Video, Dauer 01:38 mm:ss, URL, abgerufen am 17. September 2021) ."},{"text":"„Die Stadt Haßfurt produziert durch regenerative Energieerzeugung durch Wind, Sonne und Biogas mehr Strom, als Privathaushalte und Industrie dort verbrauchen. Damit ist Haßfurt ein echtes Vorbild bei der Erzeugung von Ökostrom.“","reference":"Dezentrale Versorgung – Haßfurt als Vorbild bei der Produktion von Ökostrom. In: Bayerischer Rundfunk. 17. Mai 2021 (Text und Video, Dauer 02:41 mm:ss, online abrufbar nur bis 17.05.2022 wegen des deutschen Telemediengesetzes (TMG) in Verbindung mit dem Rundfunkstaatsvertrag in der Fassung der 22. Änderung, URL, abgerufen am 17. September 2021) ."},{"text":"„Die gesamte deutsche Chemieindustrie brauche auf dem Weg zur Klimaneutralität bis 2050 \"gigantisch viel Ökostrom\".“","reference":"Brigitte Scholtes: Klimaschutz – Die deutsche Wirtschaft und der Klimawandel. In: Deutsche Welle. 9. August 2021 (URL, abgerufen am 17. September 2021) ."},{"text":"„[…] in Südspanien laufen drei Chemiewerke des Bayer-Konzerns ab 2022 mit 100 Prozent Ökostrom aus einem 590 Megawatt Solarkraftwerk.“","reference":"Gero Rueter: Erneuerbare Energien – Wo lohnen sich große Solarparks?. In: Deutsche Welle. 26. Juli 2021 (URL, abgerufen am 17. September 2021) ."},{"text":"„Um über den Bedarf hinaus verfügbaren Ökostrom zu \"bunkern\", setzen diverse Unternehmen auf Großbatterie-Anlagen - entweder aus ausgedienten oder neuen Batterien von Elektroautos. Gleich drei solcher Anlagen befinden sich in Nordrhein-Westfalen.“","reference":"Klaus Deuse: Energiewende – Neue Stromspeicher braucht das Land. In: Deutsche Welle. 17. Februar 2021 (URL, abgerufen am 17. September 2021) ."},{"text":"„Österreichs Haushalte finanzieren einen Gutteil der Kosten für die Energiewende hin zu mehr Ökostrom. Zu viel, wenn es nach der Arbeiterkammer geht. Denn die Haushalte müssten 40 bis 50 Prozent der Ökostromkosten tragen, verbrauchten jedoch nur etwa ein Viertel des Stroms.“","reference":"AK sieht Kosten ungleich verteilt. news.orf.at, ORF Online und Teletext GmbH & Co KG, Wien, Österreich, 2013, abgerufen am 17. September 2021."},{"text":"Sie verzichten auf Ökostrom, weil er zur Zeit zu teuer ist.","reference":""},{"text":"„Ökostrom ist teuer, nicht billig.“","reference":"Ulrike Herrmann: Das Ende des Kapitalismus. 1. Auflage. Kiepenheuer & Witsch, Köln 2022, ISBN 9783462002553, Seite 145"}],"idioms":[],"collocations":[],"derivations":["Ökostromabgabe","Ökostrombranche","Ökostromförderbeitrag","Ökostromerzeugung","Ökostromgesetz","Ökostromlabel","Ökostrompauschale"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökostrom","id":"614ef0686591f3"},"00f6-006b:6363df54feec52":{"word":"Ökonomisches Prinzip","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Öko·no·mi·sches Prin·zip","de-DE":"Öko·no·mi·sches Prin·zip"},"forms":[{"form":"Ökonomischem Prinzip","tags":["Dativ","Singular"]},{"form":"Ökonomisches Prinzip","tags":["Nominativ","Singular"]},{"form":"Ökonomischen Prinzips","tags":["Genitiv","Singular"]},{"form":"das Ökonomische Prinzip","tags":["Nominativ","Singular"]},{"form":"dem Ökonomischen Prinzip","tags":["Dativ","Singular"]},{"form":"ein Ökonomisches Prinzip","tags":["Nominativ","Singular"]},{"form":"des Ökonomischen Prinzips","tags":["Genitiv","Singular"]},{"form":"einem Ökonomischen Prinzip","tags":["Dativ","Singular"]},{"form":"eines Ökonomischen Prinzips","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Annahme, dass sich Wirtschaftssubjekte aufgrund der Knappheit der Güter bei ihrem wirtschaftlichen Handeln nutzenmaximierend verhalten (siehe auch Homo oeconomicus)"}],"synonyms":["Haushaltsprinzip","Rationalprinzip","Wirtschaftlichkeitsprinzip"],"origins":[],"examples":[{"text":"In nahezu allen Wirtschaftsbereichen versuchen die Wirtschaftssubjekte rational zu handeln und dem Ökonomischen Prinzip zu folgen. Dennoch ist das Ökonomische Prinzip nicht unumstritten.","reference":"Ökonomisches Prinzip. bwl-wissen.net, abgerufen am 13. April 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökonomisches Prinzip","id":"6363df54feec52"},"00f6-006b:e57477b6b0d5b5":{"word":"ökologische Nische","partOfSpeech":"Wortverbindung","gender":"die","hyphenation":{"de-CH":"öko·lo·gi·sche Ni·sche","de-DE":"öko·lo·gi·sche Ni·sche"},"forms":[{"form":"ökologische Nische","tags":["Nominativ","Singular"]},{"form":"ökologische Nischen","tags":["Nominativ","Plural"]},{"form":"ökologischer Nische","tags":["Genitiv","Singular"]},{"form":"ökologischen Nischen","tags":["Dativ","Plural"]},{"form":"ökologischer Nischen","tags":["Genitiv","Plural"]},{"form":"die ökologische Nische","tags":["Nominativ","Singular"]},{"form":"der ökologischen Nische","tags":["Genitiv","Singular"]},{"form":"eine ökologische Nische","tags":["Nominativ","Singular"]},{"form":"den ökologischen Nischen","tags":["Dativ","Plural"]},{"form":"der ökologischen Nischen","tags":["Genitiv","Plural"]},{"form":"die ökologischen Nischen","tags":["Nominativ","Plural"]},{"form":"einer ökologischen Nische","tags":["Genitiv","Singular"]},{"form":"keine ökologischen Nischen","tags":["Nominativ","Plural"]},{"form":"keinen ökologischen Nischen","tags":["Dativ","Plural"]},{"form":"keiner ökologischen Nischen","tags":["Genitiv","Plural"]}],"senses":[{"definition":"Lebensraum, der genau einer und nur einer Art die passenden Lebensbedingungen bietet"}],"synonyms":[],"origins":[],"examples":[{"text":"Kakteen besetzen eine Vielzahl von ökologischen Nischen.","reference":""},{"text":"Die Zerstörung von ökologischen Nischen ist eine ständige Gefahr für die Artenvielfalt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ökologische Nische","id":"e57477b6b0d5b5"},"00f6-006b:eb73df8244dd68":{"word":"ökonometrisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"öko·no·me·trisch","de-DE":"öko·no·me·trisch"},"forms":[{"form":"ökonometrisch","tags":["Positiv"]},{"form":"ökonometrische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ökonometrischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ökonometrischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ökonometrischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ökonometrisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ökonometrisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ökonometrisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ökonometrisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ökonometrisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die Ökonometrie betreffend, auf der Ökonometrie beruhend"}],"synonyms":[],"origins":["Derivation (Ableitung) des Substantivs Ökonometrie mit dem Suffix -isch"],"examples":[{"text":"„Als ginge es um das Geschlecht der Engel, streiten Wirtschaftwissenschaftler seit gut einem Jahrzehnt darüber, ob es ökonometrisch nachweisbar ist, daß Militärausgaben das Wachstum hemmen.“","reference":"Thomas Hanke: Reicher ohne Rüstung. In: Zeit Online. Nummer 24, 7. Juni 1991, ISSN 0044-2070 (URL, abgerufen am 13. April 2014) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ökonometrisch","id":"eb73df8244dd68"},"00f6-006b:b7aefa7f472bcf":{"word":"Ökosozialprodukt","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Öko·so·zi·al·pro·dukt","de-DE":"Öko·so·zi·al·pro·dukt"},"forms":[{"form":"Ökosozialprodukt","tags":["Nominativ","Singular"]},{"form":"Ökosozialprodukte","tags":["Nominativ","Plural"]},{"form":"Ökosozialprodukts","tags":["Genitiv","Singular"]},{"form":"Ökosozialprodukten","tags":["Dativ","Plural"]},{"form":"Ökosozialproduktes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Wert der Gesamtheit aller in einer Volkswirtschaft produzierten Güter und Dienstleistungen innerhalb eines bestimmten Zeitraums im Hinblick auf ihre Wirkung auf die Umwelt"}],"synonyms":[],"origins":["Zusammensetzung aus öko- mit dem Substantiv Sozialprodukt oder aus dem Adjektiv ökosozial und dem Substantiv Produkt"],"examples":[{"text":"Die stetige Zunahme des LKW-Verkehrs wirkt sich negativ auf das Ökosozialprodukt aus.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökosozialprodukt","id":"b7aefa7f472bcf"},"00f6-006b:433c6514a1b6da":{"word":"Ökopunkt","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·punkt","de-DE":"Öko·punkt"},"forms":[{"form":"ÖP","tags":["Kurzform"]},{"form":"Ökopunkt","tags":["Nominativ","Singular"]},{"form":"Ökopunkte","tags":["Nominativ","Plural"]},{"form":"Ökopunkts","tags":["Genitiv","Singular"]},{"form":"Ökopunkten","tags":["Dativ","Plural"]},{"form":"Ökopunktes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Einheit in behördlichen Bewertungssystemen für Eingriffe in Natur und Umwelt"}],"synonyms":[],"origins":[],"examples":[{"text":"Wegen des durch das Bauvorhaben verursachten Eingriffes in die Natur muss das Unternehmen einen Ausgleich in Höhe von 300.000 Ökopunkten erbringen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökopunkt","id":"433c6514a1b6da"},"00f6-006b:c37491b022809c":{"word":"Ökumene","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öku·me·ne","de-DE":"Öku·me·ne"},"forms":[{"form":"Ökumene","tags":["Nominativ","Singular"]},{"form":"Oikumene","tags":["variant"]},{"form":"Ökumenen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die für die Bevölkerung in der griechisch-römischen Antike bekannte Welt"},{"definition":"von Menschen besiedelter oder genutzter Lebensraum auf der Erde"},{"definition":"Gesamtheit aller Christen und ihrer Kirchen"},{"definition":"christliche, konfessionsübergreifende Bewegung zur Klärung von Glaubensfragen"}],"synonyms":["Dauersiedlungsraum","ökumenische Bewegung"],"origins":["Entlehnung aus dem Spätlateinischen von oecumene ^(→ la), das auf altgriechisch οἰκουμένη γή (oikumenē gē^☆) ^(→ grc)„bewohnte Erde“, einer Derivation zu οἰκέιν (oikein^☆) ^(→ grc) „bewohnen“ zum Substantiv οἶκος (oikos^☆) ^(→ grc) „Haus, Wohnung“ zurückgeht; vergleiche die Etymologie zu Ökonom."],"examples":[{"text":"„Sie alle strebten nach Rom, ins Zentrum der Welt, um dem Herrn der Ökumene zu huldigen.“","reference":"Timo Stickler: Griff nach der Weltmacht. In: Zeit Geschichte. Epochen. Menschen. Ideen. Nummer 2/2014, Seite 56"},{"text":"„Vollständig zur Ökumene gehören Europa, Süd- und Ostasien, der Großteil Südamerikas und der Osten der USA. Die Menschen des besiedelten Teils können bzw. könnten sich aus der eigenen Umgebung ernähren.“","reference":"Ökumene (Geographie), Biologie-Seite. Abgerufen am 26. September 2020."},{"text":"„Es gibt nur eine wahre Kirche, und zwar die Katholische - dass Papst Benedikt die traditionelle Position des Vatikans jetzt so stark betont, ist ein schwerer Rückschlag für die Ökumene. “","reference":"Ökumene: Papst düpiert Protestanten www.spiegel.de, abgerufen am 7. September 2015"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökumene","id":"c37491b022809c"},"00f6-006b:9339e54e322714":{"word":"Öko","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko","de-DE":"Öko"},"forms":[{"form":"Öko","tags":["Nominativ","Singular"]},{"form":"Ökos","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Person, die sich für die Natur einsetzt"}],"synonyms":[],"origins":["Kurzwort, belegt seit dem letzten Drittel des 20. Jahrhunderts"],"examples":[{"text":"Stefan ist Öko und Atomfreund zugleich.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Öko","id":"9339e54e322714"},"00f6-006b:b6768970d54a1b":{"word":"Ökonomin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·no·min","de-DE":"Öko·no·min"},"forms":[{"form":"Ökonom","tags":["masculine"]},{"form":"Ökonomin","tags":["Nominativ","Singular"]},{"form":"Ökonominnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Fachfrau der Wirtschaftswissenschaften"}],"synonyms":[],"origins":["Ableitung (Derivation) (Motion, Movierung) des Femininums aus der maskulinen Form Ökonom mit dem Suffix -in als Derivatem (Ableitungsmorphem)"],"examples":[{"text":"„450 Projekte sollen bis Ende des Jahres realisiert werden. Eines der ehrgeizigsten leitet die Ökonomin Zahira Asmal, mit der ich in Company’s Garden verabredet bin. Unter dem Titel \"Designing our Democracy\" bringt sie Experten jeder Ausrichtung zusammen.“","reference":"Ökonomin. In: Nr. 13. Das Digitale Wörterbuch der deutschen Sprache, 28. März 2014, archiviert vom Original am 28. März 2014 abgerufen am 29. Januar 2015 (HTML, Deutsch, Quelle: Die Zeit (online)).Parameter „archiv-url“ darf ausschließlich mit dem Parameter „archiv-datum“ zusammen verwendet werden. (Hilfe)"},{"text":"„Diese treffe die Realwirtschaft und sei daher noch kritischer als die Finanzkrise in den USA, davon ist die in den USA lebende chinesische Ökonomin He Qinglian überzeugt.“","reference":"Ökonomin. Wortschatz Lexikon Uni Leipzig, 29. Dezember 2010, abgerufen am 29. Januar 2015 (HTML, Deutsch, Quelle: EPOCH TIMES)."}],"idioms":[],"collocations":[],"derivations":["Ökonometrikerin","Ökonomikerin"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökonomin","id":"b6768970d54a1b"},"00f6-006b:fdeaac48261c1a":{"word":"Ökoenergie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·en·er·gie","de-DE":"Öko·en·er·gie"},"forms":[{"form":"Ökoenergie","tags":["Nominativ","Singular"]},{"form":"Ökoenergien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"umweltschonend hergestellte und umweltfreundlich nutzbare Energie"}],"synonyms":[],"origins":["Neuwort, gebildet aus dem Wortbildungselement Öko-, einer Verkürzung von ökologisch, in der Bedeutung „auf naturnahe Art und Weise erfolgend; der natürlichen Umwelt gerecht werdend“ und dem Substantiv Energie"],"examples":[{"text":"Trotz niedrigerer Förderungen auf den wichtigsten europäischen Märkten für Ökoenergie einerseits, und sehr konkurrenzfähigen Erdgaspreisen in den USA andererseits, würden die Investitionen zum ersten Mal seit drei Jahren wieder steigen.","reference":"Im Aufwind: Investitionen in Ökoenergien. Erstmals seit 2011 wieder steigende Zahlen für regenerative Energien. In: presstext Nachrichtenagentur. 21. Januar 2015 (Online, abgerufen am 21. Februar 2016) ."},{"text":"Der Anteil der Ökoenergie hat in den ersten Monaten des Jahres einen neuen Rekordwert erreicht.","reference":"afp: Deutschland: Anteil der Ökoenergie steigt auf neuen Rekordwert von 27 Prozent. In: Zeit Online. 9. Mai 2014, ISSN 0044-2070 (URL, abgerufen am 21. Februar 2016) ."},{"text":"Die EU-Kommission schätzt die Höhe staatlicher Fördermittel für Europas Atombranche ähnlich hoch ein wie die Zuschüsse für Ökoenergien.","reference":"dpa: Akw-Förderung in EU ähnlich hoch wie für Ökoenergien. EU-Kommission. In: Handelsblatt Online. 24. Juli 2013, ISSN 0017-7296 (URL, abgerufen am 21. Februar 2016) ."},{"text":"„Die zusätzlichen Kosten durch Ökoenergien betragen bereits heute für einen Privathaushalt 150 Euro und werden zukünftig weiter steigen. …“","reference":"Fehlender Parameter (Hilfe) Niedersächsisches Ministerium für Umwelt, Energie und Klimaschutz, 15. Oktober 2010, abgerufen am 21. Februar 2016."},{"text":"Fazit der Untersuchung: Das Ziel, bis zum Jahr 2020 rund 70 Prozent der Raumwärme und Warmwasserversorgung der Haushalte mit Ökoenergien abzudecken, ist nur in Kombination mit einer breit angelegten thermischen Sanierung von Häusern und Wohnungen möglich.","reference":"Molliges Klima für Ökoenergien. In: Der Standard digital. 6. April 2006 (URL, abgerufen am 21. Februar 2016) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökoenergie","id":"fdeaac48261c1a"},"00f6-006b:b67db8b926d8c2":{"word":"Ökonomieprofessor","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·no·mie·pro·fes·sor","de-DE":"Öko·no·mie·pro·fes·sor"},"forms":[{"form":"Ökonomieprofessor","tags":["Nominativ","Singular"]},{"form":"Ökonomieprofessors","tags":["Genitiv","Singular"]},{"form":"Ökonomieprofessoren","tags":["Nominativ","Plural"]},{"form":"Ökonomieprofessorin","tags":["feminine"]}],"senses":[{"definition":"Professor für Ökonomie"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ökonomie und Professor"],"examples":[{"text":"„So hat der US-amerikanische Ökonomieprofessor Theodore Burczak ein vielbeachtetes Buch darüber geschrieben, wie ein sozialistisches Wirtschaftsmodell aussehen könnte, das das Wissensproblem von Hayek berücksichtigt.“","reference":"Wikipedia-Artikel „Friedrich August von Hayek“ (Stabilversion)"},{"text":"„Karsten Emser, dem früheren Ökonomieprofessor, wurde in dem von der Sowjetischen Militäradministration eingesetzten antifaschistischen Magistrat von Groß-Berlin das Wirtschaftsressort zugewiesen mit der vordringlichen Aufgabe, den dringendsten Bedarf der Bevölkerung sicherzustellen.“","reference":"Christoph Hein: Das Narrenschiff. Roman. 7. Auflage. Suhrkamp, Berlin 2025, ISBN 978-3-518-43226-6 , Seite 19. 1. Auflage 2025."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökonomieprofessor","id":"b67db8b926d8c2"},"00f6-006b:f6a67d33efd21a":{"word":"Ökonomieprofessorin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·no·mie·pro·fes·so·rin","de-DE":"Öko·no·mie·pro·fes·so·rin"},"forms":[{"form":"Ökonomieprofessor","tags":["masculine"]},{"form":"Ökonomieprofessorin","tags":["Nominativ","Singular"]},{"form":"Ökonomieprofessorinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Professorin für Ökonomie"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Ökonomieprofessor mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Dort wurde 1984 auf Initiative der Ökonomieprofessorin Rhonda Sharp versucht, den Staatshaushalt gerechter zwischen Frauen und Männern aufzuteilen.“","reference":"Wikipedia-Artikel „Gender Budgeting“ (Stabilversion)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökonomieprofessorin","id":"f6a67d33efd21a"},"00f6-006b:93bb97ac59e8af":{"word":"Ökonomiestudium","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Öko·no·mie·stu·di·um","de-DE":"Öko·no·mie·stu·di·um"},"forms":[{"form":"Ökonomiestudien","tags":["Nominativ","Plural"]},{"form":"Ökonomiestudium","tags":["Nominativ","Singular"]},{"form":"Ökonomiestudiums","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Studium der Ökonomie"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Ökonomie und Studium"],"examples":[{"text":"Ihr Ökonomiestudium schloss sie mit summa cum laude ab.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökonomiestudium","id":"93bb97ac59e8af"},"00f6-006b:598297acc49b2e":{"word":"öko-","partOfSpeech":"Präfix","gender":"","hyphenation":{"de-CH":"öko-","de-DE":"öko-"},"forms":[],"senses":[{"definition":"Haus, Haushalt; die bewusste Beschäftigung mit der Umwelt und deren Problemen und Belastungen"}],"synonyms":[],"origins":["von griechisch οἶκος (oikos^☆) ^(→ grc) Haus"],"examples":[{"text":"Die Ökologie ist ein Teilgebiet der Biologie.","reference":""},{"text":"Die Ökotrophologie ist die Haushalts- und Ernährungswissenschaft.","reference":""},{"text":"Von einer Ökobank erwartet man, dass sie keine umweltbelastenden Projekte finanziert.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"öko-","id":"598297acc49b2e"},"00f6-006b:5eeec6c5c7844c":{"word":"öko","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"öko","de-DE":"öko"},"forms":[{"form":"öko","tags":["Positiv"]}],"senses":[{"definition":"ökologisch (im Sinne der Natur und Umwelt, zu deren Schutz)"}],"synonyms":[],"origins":[],"examples":[{"text":"Ich bin öko, weil ich daran glaube, dass auch das Verhalten einer einzelnen Person einen Unterschied macht.","reference":""},{"text":"Ist öko das Gleiche wie fair oder bio?","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"öko","id":"5eeec6c5c7844c"},"00f6-006b:e437f98591b66f":{"word":"Ökotrophologie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·tropho·lo·gie","de-DE":"Öko·tropho·lo·gie"},"forms":[{"form":"Ökotrophologie","tags":["Nominativ","Singular"]},{"form":"Oecotrophologie","tags":["alternative"]}],"senses":[{"definition":"Lehre vom Haushalten, der Haushaltsführung und der Ernährung"}],"synonyms":["Haushalts- und Ernährungswissenschaft","Oecotrophologie"],"origins":["Zusammensetzung der Vorsilbe öko- mit dem Substantiv Trophologie"],"examples":[{"text":"Nach dem Studium der Ökotrophologie kann man Ernährungsberater werden.","reference":""},{"text":"Die Ökotrophologie verknüpft medizinische, naturwissenschaftliche, psychologische, soziologische und ökonomische Aspekte.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökotrophologie","id":"e437f98591b66f"},"00f6-006b:8626938d1829a7":{"word":"Ökonomik","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·no·mik","de-DE":"Öko·no·mik"},"forms":[{"form":"Ökonomik","tags":["Nominativ","Singular"]},{"form":"Ökonomiken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Wirtschaftswissenschaft"},{"definition":"Wirtschaft beispielsweise eines Landes"}],"synonyms":["Wirtschaftswissenschaft","Wirtschaftswissenschaften","Ökonomie"],"origins":["zu lateinisch oeconomicus ^(→ la) („ökonomisch“)"],"examples":[{"text":"„Natürlich ist die Erwerbsweise, die Produkte unmittelbar aus der Natur gewinnt (durch Ackerbau, Tierhaltung oder Jagd), sie ist von Natur Teil der Ökonomik.“","reference":"Aristoteles: Politik, Hamburg 2012, S. XX."},{"text":"„Bereits bei der ersten Durchsicht bemerkte er den völlig verschiedenen Ansatz bei der Beurteilung der Ökonomik.“","reference":"Christoph Hein: Das Narrenschiff. Roman. 7. Auflage. Suhrkamp, Berlin 2025, ISBN 978-3-518-43226-6 , Seite 661. 1. Auflage 2025."},{"text":"Die deutsche Ökonomik lässt nach.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökonomik","id":"8626938d1829a7"},"00f6-006b:040d6d619cddbf":{"word":"Ökologin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·lo·gin","de-DE":"Öko·lo·gin"},"forms":[{"form":"Ökologe","tags":["masculine"]},{"form":"Ökologin","tags":["Nominativ","Singular"]},{"form":"Ökologinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die sich in großem Ausmaß mit dem Fachgebiet der Ökologie beschäftigt"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Ökologe, Subtraktionsfuge -e und mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"Als Ökologin untersucht sie nun Schadstoffverbreitungen in Boden, Wasser und Luft.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökologin","id":"040d6d619cddbf"},"00f6-006b:7addb9927d2224":{"word":"ökumenisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"öku·me·nisch","de-DE":"öku·me·nisch"},"forms":[{"form":"ökumenisch","tags":["Positiv"]},{"form":"ökumenische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"ökumenischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"ökumenischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"ökumenischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"ökumenisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist ökumenisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist ökumenisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist ökumenisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind ökumenisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die gesamte vom Menschen bewohnte Erde betreffend, der Lebensraum auf der Erde"},{"definition":"die Bestrebungen von Christen nach Einigung in religiösen Fragen betreffend; gemeinsam von katholischen und evangelischen Christen getragen"},{"definition":"alle katholischen Christen (der gesamten Welt) umfassend"}],"synonyms":["zwischenkirchlich","überkirchlich"],"origins":["Ableitung zu Ökumene mit dem Derivatem (Ableitungsmorphem) -isch"],"examples":[{"text":"„Seitdem der Glaube aufgehört hat, dass ein Gott die Schicksale der Welt im Grossen leite und, trotz aller anscheinenden Krümmungen im Pfade der Menschheit, sie doch herrlich hinausführe, müssen die Menschen selber sich ökumenische, die ganze Erde umspannende Ziele stellen.“","reference":"Friedrich Nietzsche: Menschliches, Allzumenschliches. E. Schmeitzner, 1878, Seite 27 ."},{"text":"„Vor zehn Jahren luden am Rande des ersten ökumenischen Kirchentags in Berlin evangelische und katholische Christen zu einem gemeinsamen Abendmahl in die Berliner Gethsemanekirche ein.“","reference":"Matthias Morgenroth: Rückblick – Abendmahls-Eklat beim ökumenischen Kirchentag 2003. In: Bayerischer Rundfunk. 30. Mai 2003 (URL, abgerufen am 20. November 2019) ."},{"text":"„Für 2021 ist zum dritten Mal ein Ökumenischer Kirchentag geplant.“ [Anmerkung: ökumenisch wird als Adjektiv kleingeschrieben, solange es nicht Bestandteil von Eigennamen ist, beispielsweise in \"Ökumenischer Rat der Kirchen\": im Beispiel ist es also fälschlicherweise großgeschrieben)]","reference":"Evangelischer Kirchentag – Kirchentag endet mit politischen Appellen. In: Deutsche Welle. 23. Juni 2019 (URL, abgerufen am 20. November 2019) ."},{"text":"„Mit einem Gottesdienst […] in Bochum ist heute das eintägige ökumenische Fest „Wie im Himmel so auf Erden“ zu Ende gegangen.“","reference":"Carsten Splitt: Der ökumenische Weg geht weiter. ekd.de, Evangelische Kirche in Deutschland (EKD), Hannover, Deutschland, 16. September 2017, abgerufen am 20. November 2019."},{"text":"„Bis zum 11. Mai läuft die Kampagne [Anmerkung: der beiden christlichen Kirchen in Deutschland], die am Sonnabend mit einem ökumenischen Gottesdienst in der Marktkirche in Hannover eröffnet worden ist.“","reference":"Suizidprävention: Kirchen wollen ein Tabu brechen. In: Norddeutscher Rundfunk. 4. Mai 2019 (URL, abgerufen am 20. November 2019) ."},{"text":"„In der Münchner Frauenkirche fand am Nachmittag ein ökumenischer Gedenkgottesdienst zum Amoklauf am 22. Juli im Olympia Einkaufszentrum statt.“","reference":"Markus Kaiser: Gottesdienst in Liebfrauendom – Trauer nach Terror von München. In: Bayerischer Rundfunk. 31. Juli 2016 (URL, abgerufen am 20. November 2019) ."},{"text":"„In wenigen Monaten starten die 42. Passionsspiele in Oberammergau. Erstmals gab es den Segen ökumenisch von beiden Kirchen.“","reference":"Alkyone Karamanolis: Segen für Passionsspiel – Christian Stückl: Passionsgeschichte hat politische Botschaft. In: Bayerischer Rundfunk. 5. November 2019 (URL, abgerufen am 20. November 2019) ."},{"text":"„»Die Beziehungen der Rumänischen Orthodoxen Kirche zur Römisch-Katholischen Kirche sind absolut elegant und basieren auf einem ökumenischen Dialog, der als historisch angesehen werden kann«, versicherte der Sprecher des rumänisch-orthodoxen Patriarchats, Vasile Banescu, im DW-Interview.“","reference":"Cristian Stefanescu: Papst Franziskus in Rumänien: \"Gehen wir gemeinsam\". In: Deutsche Welle. 30. Mai 2019 (URL, abgerufen am 20. November 2019) ."},{"text":"„Am geplanten ökumenischen Krankenhaus in Flensburg sollen keine Schwangerschaftsabbrüche durchgeführt werden. Darauf haben sich die beiden kirchlichen Träger Diakonie und Malteser geeinigt.“","reference":"Neue Flensburger Klinik will keine Abtreibungen. In: Norddeutscher Rundfunk. 30. Oktober 2019 (URL, abgerufen am 20. November 2019) ."},{"text":"„Die geplante ökumenische Eucharistiefeier in Dübendorf fand nicht statt. Aus Angst vor negativen Folgen nahmen die zwei katholischen Priester nur als Gäste am stattdessen durchgeführten Abendmahl teil. Der orthodoxe Priester erschien gar nicht.“","reference":"Schweiz - Der Mut zur Ökumene fehlt. In: Schweizer Radio und Fernsehen. 30. Juni 2013 (URL, abgerufen am 20. November 2019) ."},{"text":"„17 Uhr Beginn Martinsumzug in der Innenstadt mit dem Heiligen Martin auf dem Pferd zur Kreuzkirche. […] 17:30 Uhr beginnt eine ökumenische Andacht.“","reference":"Terminübersicht – Laterne, Laterne: Hier feiern Sachsen das Martinsfest. In: Mitteldeutscher Rundfunk. 11. November 2019 (URL, abgerufen am 20. November 2019) ."},{"text":"„1590 erkennt eine ökumenische Synode in Konstantinopel das neue Patriarchat als eigenständige (autokephale) Kirche mit völliger Rechts-, Verwaltungs- und Lehrautonomie an“.","reference":"Die Russisch-Orthodoxe Kirche, Von Konstantinopel über Kiew nach Moskau. In: Bayerischer Rundfunk. 5. April 2017 (URL, abgerufen am 20. November 2019) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"ökumenisch","id":"7addb9927d2224"},"00f6-006b:600d7e1c4fd57a":{"word":"Ökozid","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Öko·zid","de-DE":"Öko·zid"},"forms":[{"form":"Ökozid","tags":["Nominativ","Singular"]},{"form":"Ökozide","tags":["Nominativ","Plural"]},{"form":"Ökozids","tags":["Genitiv","Singular"]},{"form":"Ökoziden","tags":["Dativ","Plural"]}],"senses":[{"definition":"durch den Menschen (vorsätzlich, billigend) ausgelöste Zerstörung (von Teilgebieten) der Umwelt"}],"synonyms":[],"origins":["Kompositum, zusammengesetzt aus öko- und -zid"],"examples":[{"text":"„Es gibt jedoch internationale Initiativen, Ökozid als fünftes Verbrechen neben Völkermord, Verbrechen gegen die Menschlichkeit, Kriegsverbrechen und Verbrechen der Aggression im Römischen Statut des Internationalen Strafgerichtshofs aufzuführen.“","reference":"Wikipedia-Artikel „Ökozid“"},{"text":"„Wer vorsätzlich schwere Umweltschäden verursacht, soll bis zu zehn Jahre in Haft: Das französische Parlament hat sich dafür ausgesprochen, ‚Ökozid‘ in einem neuen Gesetzespaket zum Straftatbestand zu erklären.“","reference":"\"Ökozid\" soll Straftatbestand werden. Abgerufen am 18. April 2021."}],"idioms":[],"collocations":[],"derivations":["ökozid"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökozid","id":"600d7e1c4fd57a"},"00f6-006b:157050bc7fcb5a":{"word":"ökonomisieren","partOfSpeech":"Verb","gender":"","hyphenation":{"de-CH":"öko·no·mi·sie·ren","de-DE":"öko·no·mi·sie·ren"},"forms":[{"form":"haben","tags":["Hilfsverb","Perfekt"]},{"form":"ökonomisier!","tags":["Imperativ","Singular"]},{"form":"ökonomisiere","tags":["Präsens"]},{"form":"ökonomisiert","tags":["Präsens"]},{"form":"ökonomisiere!","tags":["Imperativ","Singular"]},{"form":"ökonomisieren","tags":["Aktiv","Infinitiv","Präsens"]},{"form":"ökonomisierst","tags":["Präsens"]},{"form":"ökonomisiert!","tags":["Imperativ","Plural"]},{"form":"ökonomisierte","tags":["Präteritum"]},{"form":"ökonomisierend","tags":["Partizip","Präsens","Aktiv"]},{"form":"ökonomisieret!","tags":["Imperativ","archaic","2. Person","Plural","Präsens","Aktiv"]},{"form":"du ökonomisierst","tags":["2. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ich ökonomisiere","tags":["1. Person","Singular","Präsens","Aktiv","Indikativ"]},{"form":"ihr ökonomisiert","tags":["2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"zu ökonomisieren","tags":["Aktiv","erweitert","Infinitiv"]},{"form":"du ökonomisierest","tags":["2. Person","Singular","Präsens","Aktiv","Konjunktiv I"]},{"form":"ich ökonomisierte","tags":["1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr ökonomisieret","tags":["archaic","2. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"sie ökonomisieren","tags":["3. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"wir ökonomisieren","tags":["1. Person","Plural","Präsens","Aktiv","Indikativ"]},{"form":"ökonomisiert sein","tags":["statal-passive","Infinitiv","Präsens"]},{"form":"du ökonomisiertest","tags":["2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"habe ökonomisiert!","tags":["Imperativ","uncommon","2. Person","Singular","Perfekt","Aktiv"]},{"form":"habt ökonomisiert!","tags":["Imperativ","uncommon","2. Person","Plural","Perfekt","Aktiv"]},{"form":"ich ökonomisierete","tags":["archaic","1. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr ökonomisiertet","tags":["2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"sie ökonomisierten","tags":["3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir ökonomisierten","tags":["1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"zu ökonomisierende","tags":["Partizip","gerundive"]},{"form":"ökonomisieren Sie!","tags":["Imperativ","Höflichkeitsform","Präsens","Aktiv"]},{"form":"ökonomisiert haben","tags":["Aktiv","Infinitiv","Perfekt"]},{"form":"du ökonomisieretest","tags":["archaic","2. Person","Singular","Präteritum","Aktiv","Indikativ"]},{"form":"ihr ökonomisieretet","tags":["archaic","2. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"sie ökonomisiereten","tags":["archaic","3. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"wir ökonomisiereten","tags":["archaic","1. Person","Plural","Präteritum","Aktiv","Indikativ"]},{"form":"zu ökonomisierender","tags":["Partizip","gerundive"]},{"form":"ökonomisiert werden","tags":["Vorgangspassiv","Infinitiv","Präsens"]},{"form":"du hast ökonomisiert","tags":["2. Person","Singular","Perfekt","Aktiv","Indikativ"]},{"form":"ökonomisiert zu sein","tags":["statal-passive","erweitert","Infinitiv"]},{"form":"ich habe ökonomisiert","tags":["1. Person","Singular","Perfekt","Aktiv","Indikativ"]}],"senses":[{"definition":"ökonomisch gestalten, nach ökonomischen Prinzipien organisieren"}],"synonyms":[],"origins":["Derivation (Ableitung) zum Substantiv Ökonomie mit dem Derivatem (Ableitungsmorphem) -isier und der Flexionsendung -en"],"examples":[{"text":"Der kleinbäuerliche Betrieb wurde ökonomisiert.","reference":""},{"text":"„Ängste, die Industrie könnte die Universität ökonomisieren bzw. beherrschen, können nur aus einer Schwäche und nicht aus einer Stärke der Universität erwachsen“, so Pöhl weiter.","reference":"Partnerschaftliches Verhältnis zur Wirtschaft. Montan Universität Leoben, 21. Juni 2002, abgerufen am 20. Mai 2021."},{"text":"Wir ökonomisieren mehr und mehr unser Leben – und haben gleichzeitig immer weniger Zeit. Logisch: wir verkaufen ja unsere Zeit und leben immer häufiger nach dem Grundsatz ‚Zeit ist Geld‘.","reference":"Silke Hohmuth: Geteilte Zeit ist Menschlichkeit. menschbank.de, abgerufen am 20. Mai 2021."},{"text":"Wir brauchen die Vielfalt, und nicht alles ist zu ökonomisieren und zu materialisieren, sondern auch der geisteswissenschaftliche Bereich ist einfach zu stärken und genau vor einer solchen Tendenz in Schutz zu nehmen.","reference":"Stefan Schennach: Stenographisches Protokoll; 781. Sitzung des Bundesrates der Republik Österreich. www.parlament.gv.at, 18. Februar 2010, Seite 79, abgerufen am 20. Mai 2021."},{"text":"Der Patient soll auch durch das Erlernen gezielter Atemtechniken, die Atmung ökonomisieren, wieder mehr Atemkontrolle erlangen und somit seine Lebensqualität steigern.","reference":"Miriam Subhieh: Atemphysiotherapie. www.atempunkt.net, 2016, abgerufen am 20. Mai 2021."}],"idioms":[],"collocations":[],"derivations":["Ökonomisieren","ökonomisierend","ökonomisiert","Ökonomisierung"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ökonomisieren","id":"157050bc7fcb5a"},"00f6-006b:2d25334fdd1ff6":{"word":"ökologischer Fußabdruck","partOfSpeech":"Wortverbindung","gender":"der","hyphenation":{"de-CH":"öko·lo·gi·scher Fuss·ab·druck","de-DE":"öko·lo·gi·scher Fuß·ab·druck"},"forms":[{"form":"ökologische Fußabdrücke","tags":["Nominativ","Plural"]},{"form":"ökologischem Fußabdruck","tags":["Dativ","Singular"]},{"form":"ökologischen Fußabdruck","tags":["Akkusativ","Singular"]},{"form":"ökologischen Fußabdrucks","tags":["Genitiv","Singular"]},{"form":"ökologischer Fussabdruck","tags":["alternative","Switzerland","Liechtenstein"]},{"form":"ökologischer Fußabdrücke","tags":["Genitiv","Plural"]},{"form":"ökologischen Fußabdruckes","tags":["Genitiv","Singular"]},{"form":"ökologischen Fußabdrücken","tags":["Dativ","Plural"]},{"form":"der ökologische Fußabdruck","tags":["Nominativ","Singular"]},{"form":"dem ökologischen Fußabdruck","tags":["Dativ","Singular"]},{"form":"den ökologischen Fußabdruck","tags":["Akkusativ","Singular"]},{"form":"ein ökologischer Fußabdruck","tags":["Nominativ","Singular"]},{"form":"der ökologischen Fußabdrücke","tags":["Genitiv","Plural"]},{"form":"des ökologischen Fußabdrucks","tags":["Genitiv","Singular"]},{"form":"die ökologischen Fußabdrücke","tags":["Nominativ","Plural"]},{"form":"den ökologischen Fußabdrücken","tags":["Dativ","Plural"]},{"form":"des ökologischen Fußabdruckes","tags":["Genitiv","Singular"]},{"form":"einem ökologischen Fußabdruck","tags":["Dativ","Singular"]},{"form":"einen ökologischen Fußabdruck","tags":["Akkusativ","Singular"]},{"form":"eines ökologischen Fußabdrucks","tags":["Genitiv","Singular"]},{"form":"keine ökologischen Fußabdrücke","tags":["Nominativ","Plural"]},{"form":"eines ökologischen Fußabdruckes","tags":["Genitiv","Singular"]},{"form":"keiner ökologischen Fußabdrücke","tags":["Genitiv","Plural"]},{"form":"keinen ökologischen Fußabdrücken","tags":["Dativ","Plural"]}],"senses":[{"definition":"notwendige Fläche auf der Erde pro Person, die für die Produktion von Gütern und Dienstleistungen (beispielsweise von Nahrung, Kleidung, Maschinen, Energie, Müllentsorgung, etc.) für den Menschen benötigt wird"}],"synonyms":[],"origins":["das Wort ist ein Neologismus der 2000er Jahre"],"examples":[{"text":"Wir können unseren ökologischen Fußabdruck verkleinern, indem wir weniger oder kein Fleisch essen, weniger reisen, das Auto stehen lassen und die Häuser dämmen.","reference":""},{"text":"Der Vergleich von armen und reichen Deutschen zeigt, dass die Reichen einen viel gößeren ökologischen Fußabdruck haben, völlig egal, ob sie umweltbewusst sind oder nicht.","reference":""},{"text":"[Silke van Dyk:] „»Interessant ist: Die in Deutschland, die sich am ökologischsten gerieren, haben oft den größten ökologischen Fußabdruck. Ein Hartz-IV-Empfänger verkörpert nicht den ökologisch bewussten Lebensstil, hat dennoch einen vergleichsweise geringen Fußabdruck gegenüber denen mit Öko-Haus und Manufactum-Möbeln.«“","reference":"Jonas Weyrosta: „Radikale Umverteilung stärkt die Nachfrage“. freitag.de, der Freitag Mediengesellschaft mbh & Co. KG, Berlin, Deutschland, abgerufen am 6. Mai 2022 (Ausgabe 39/2017, Interview mit Silke van Dyk, Professorin für Politische Soziologie an der Friedrich-Schiller-Universität Jena)."},{"text":"„Die biologisch, produktive Oberfläche der Erde (Biokapazität) war 2014 1,68 gHa (globale Hektar pro Person), der ökologische Fußabdruck 2,84 gHa.“","reference":"Wikipedia-Artikel „Tragfähigkeit_(Ökologie)“ (Stabilversion)"},{"text":"„Die weltweite Corona-Pandemie hat den ökologischen Fußabdruck der Menschheit um zehn Prozent schrumpfen lassen und das Datum des sogenannten Erdüberlastungstags um mehr als drei Wochen nach hinten verschoben.“","reference":"Erdüberlastungstag – 2020 schrumpft weltweit der ökologische Fußabdruck. In: Deutsche Welle. 20. August 2020 (URL, abgerufen am 6. Mai 2022) ."},{"text":"„Hauptverantwortlich dafür, dass das natürliche Ressourcenbudgets des Planeten regelmäßig überschritten wird, sind die CO₂-Emissionen, die derzeit 60 Prozent des ökologischen Fußabdrucks der Menschheit ausmachen.“","reference":"Anne-Sophie Brändlin: Umwelt – Deutscher Erdüberlastungstag: \"So geht’s nicht weiter\". In: Deutsche Welle. 4. Mai 2022 (URL, abgerufen am 6. Mai 2022) ."},{"text":"„In den ökologischen Fußabdruck werden eingerechnet: die Flächen, die zur Produktion von Nahrung, Kleidung, Möbeln und sonstigen Gebrauchsgegenständen benötigt werden, aber auch die Flächen für das Wohnen, den produzierten Müll, für die Bereitstellung von Energie und das Binden des freigesetzten Kohlendioxids.“","reference":"Martina Frietsch, Wiebke Ziegler: Globaler Wandel – Der ökologische Fußabdruck. In: Südwestrundfunk. 28. Oktober 2019 (URL, abgerufen am 6. Mai 2022) ."},{"text":"„Die Jahre von 1993 bis 2009 – das ist der Zeitraum, den die neue Studie abdeckt. Wie stark hat sich der ökologische Fußabdruck des Menschen in diesen 16 Jahren verändert?“","reference":"Volker Mrasek: Ressourcen-Verbrauch – Ökologischer Fußabdruck neu berechnet. In: Deutschlandradio. 24. August 2016 (Deutschlandfunk / Köln, Sendereihe: Forschung aktuell, URL, abgerufen am 6. Mai 2022) ."},{"text":"„Als Grit Dielmann ihren ökologischen Fußabdruck berechnete, traf sie fast der Schlag. Würden alle Menschen auf der Welt so leben wie sie und ihre Familie, bräuchte es vier Erden.“","reference":"Simone Schmollack: Ökobilanz und Einkommen: Öko ist (k)ein Luxusproblem. In: taz.de. 20. September 2019, ISSN 2626-5761 (URL, abgerufen am 6. Mai 2022) ."},{"text":"„»Nach einer Vorlesung kamen zwei Studierende zu mir und erzählten von dem Versuch, ihren ökologischen Fußabdruck so gering wie möglich zu halten«, berichtet Scheibler von den Anfängen des Projekts.“","reference":"Susanne Schwarz: Studie zu Lebensmitteln und CO2-Ausstoß: Ist Bio schlecht fürs Klima?. In: taz.de. 7. Juni 2020, ISSN 2626-5761 (URL, abgerufen am 6. Mai 2022) ."},{"text":"„Im Kunstmuseum Wolfsburg will man andere Wege gehen, um den ökologischen Fußabdruck zu verkleinern.“","reference":"Kunstmuseum Wolfsburg will ökologischen Fußabdruck verkleinern. In: Norddeutscher Rundfunk. 9. September 2021 (URL, abgerufen am 6. Mai 2022) ."},{"text":"„Wenn die Tomaten in Ihrem Garten nicht reichen, dann gehen Sie in den Supermarkt nebenan und kaufen eben Tomaten ein, die anderswo gewachsen sind. Das ist im Kleinen das, was Deutschland seit Jahrzehnten im Großen macht: Wir leben auf so großem Fuße, dass auch unser ökologischer Fußabdruck entsprechend riesig ist.“","reference":"Heike Westram: Deutschland lebt seit 3. Mai ökologisch auf Pump. In: Bayerischer Rundfunk. 6. Mai 2019 (URL, abgerufen am 6. Mai 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"ökologischer Fußabdruck","id":"2d25334fdd1ff6"},"00f6-006b:90cb45c79ab524":{"word":"Ökobilanz","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·bi·lanz","de-DE":"Öko·bi·lanz"},"forms":[{"form":"Ökobilanz","tags":["Nominativ","Singular"]},{"form":"Ökobilanzen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Auswirkungen eines Produktes auf die Umwelt durch Produktion, Vertrieb, Nutzung und Entsorgung; für Dienstleistungen oder persönliches Verhalten; Ergebnis einer systematischen Analyse zur Umweltverträglichkeit"}],"synonyms":["Lebenszyklusanalyse","Umweltbilanz"],"origins":["Das Wort ist ein Neologismus der 1980er Jahre; es wird gebildet aus dem Wortbildungselement Öko-, einer Verkürzung von ökologisch, in der Bedeutung „auf naturnahe Art und Weise erfolgend, der natürlichen Umwelt gerecht werdend“ und dem Substantiv Bilanz"],"examples":[{"text":"Die Ökobilanz von Wegwerfwindeln ist katastrophal.","reference":""},{"text":"Die Ökobilanz des Heizens mit Holz wird nicht mehr ganz so positiv gesehen, wie vor ein paar Jahren, wegen der dabei entstehenden hohen Emissionen von Feinstaub.","reference":""},{"text":"„Die Personenluftfahrt hat eine schlechte Ökobilanz.“","reference":"Luftfahrt – Flugzeuge sollen mit Windkraft fliegen. In: Deutsche Welle. 2. August 2019 (URL, abgerufen am 18. November 2022) ."},{"text":"„Vergleicht man eine Tasse Tee mit einer Tasse Kaffee, dann ist die Ökobilanz des Tees mindestens drei- bis viermal besser – je nachdem, wie man die einzelnen Aspekte gewichtet. Schaut man sich zum Beispiel den Flächenverbrauch an, dann schneidet die Herstellung von Tee deutlich besser ab.“","reference":"Gábor Paál: Wie ist die Ökobilanz von Tee im Vergleich zu Kaffee?. In: Südwestrundfunk. 21. Oktober 2019 (URL, abgerufen am 18. November 2022) ."},{"text":"„Da zur Zeit der meiste Strom noch aus fossilen Brennstoffen gewonnen wird, ist die Ökobilanz von Elektroautos nur leicht besser als von Verbrennern.“","reference":"Der Faktencheck zur Sendung vom 04.02.2019. In: Westdeutscher Rundfunk. 4. Februar 2019 (URL, abgerufen am 18. November 2022) ."},{"text":"„Durch diese Maßnahmen lässt sich die Ökobilanz des Gebäudes gegenüber konventionellen Fertighäusern um ein vielfaches verbessern und bis zur völligen CO₂-Neutralität in der Herstellung optimieren.“","reference":"Thomas Reiter, Markus Leeb, Tobias Weiß: RWF Coachingprojekt Biosphärenhaus Lungau. fh-salzburg.ac.at, Fachhochschule Salzburg GmbH, 31. Juli 2014, abgerufen am 18. November 2022."},{"text":"[Mehrwegflachen:] […] „je öfter eine Flasche neu befüllt wird, desto besser ist ihre Ökobilanz.“","reference":"Mehrwegflaschen aus Plastik oder Glas: Was ist nachhaltiger?. In: Norddeutscher Rundfunk. 10. November 2022 (URL, abgerufen am 18. November 2022) ."},{"text":"„Äpfel gibt es das ganze Jahr über im Supermarkt. Aber welche haben eine bessere Ökobilanz? Die vom Bodensee oder die aus Übersee?“","reference":"Alexander Dallmus: Bodensee- oder Neuseeland-Apfel – Wie steht's um die Ökobilanz von Äpfeln?. In: Bayerischer Rundfunk. 25. April 2018 (URL, abgerufen am 18. November 2022) ."},{"text":"„Mit Blick auf den CO₂-Ausstoß erzielt pflanzliche Milch eine [um den Faktor 4,5] bessere Ökobilanz als Kuhmilch.“","reference":"Sandra Ahrens: CO2-Emissionen von Kuhmilch und pflanzlicher Milch im Vergleich 2018. de.statista.com, Statista GmbH, Hamburg, Deutschland, 2. Januar 2024, abgerufen am 9. August 2024."},{"text":"„Dennoch hat die Bambus-FFP2-Maske Made in Germany unterm Strich vermutlich eine bessere Ökobilanz als eine herkömmliche.“","reference":"Maren Keller, Sebastian Späth, Katherine Rydlink: Stil-Highlights der Woche – Knackig und fest in den Herbst. In: Spiegel Online. 10. September 2022, ISSN 0038-7452 (URL, abgerufen am 18. November 2022) ."},{"text":"[Papier aus Gras:] „Zu der Ökobilanz der Herstellung hat Prof. Valkama keine Zahlen, doch er vermutet, dass viele Substanzen aus dem Grünschnitt ins Wasser gelangen, die man später herausfiltern“ [muss.]","reference":"Matilda Jordanova-Duda: Nachhaltige Verpackungen – Wiese als Karton: Verpackungen aus Graspapier. In: Deutsche Welle. 2. Juli 2019 (URL, abgerufen am 18. November 2022) ."},{"text":"„[…] Menschen mit hohem Umweltbewusstsein [haben] laut Studie nicht zwangsläufig eine gute persönliche Ökobilanz. Menschen aus einfacheren Milieus, die sich selbst am wenigsten sparsam beim Ressourcenschutz einschätzen und die ein eher geringeres Umweltbewusstsein haben, belasten die Umwelt hingegen am wenigsten.“","reference":"Wer mehr verdient, lebt meist umweltschädlicher – Blinde Flecken oft bei Mobilität und Wohnen. Bundesrepublik Deutschland, Umweltbundesamt, Präsidialbereich / Presse- und Öffentlichkeitsarbeit, Internet, Dessau-Roßlau, Deutschland, 4. August 2016, abgerufen am 18. November 2022."},{"text":"„In den USA ergab die detaillierte Ökobilanz einer regenerativen Farm, dass die Treibhausgasemissionen für jedes Kilogramm Fleisch um 66 Prozent niedriger sind als bei konventionellen Alternativen, aber 2,5 Mal mehr Land beanspruchen,“ […].","reference":"Ajit Niranjan: UN-Studie – Wie unsere Lebensmittel das Artensterben beschleunigen. In: Deutsche Welle. 3. Februar 2021 (URL, abgerufen am 18. November 2022) ."},{"text":"„Der Bundesrat wird beauftragt, eine Ökobilanz der Schweizer Armee aufzustellen.“","reference":"Fehlender Parameter (Hilfe) parlament.ch, Die Bundesversammlung — Das Schweizer Parlament, Parlamentsdienste, Bern, Schweiz, 5. März 2008, abgerufen am 17. November 2022 (Deutsch)."},{"text":"„»Ich glaube nicht, dass wir die richtigen Ökobilanzen erstellt haben, um sagen zu können, dass Hanf irgendwelche Vorteile gegenüber der Verwendung von Mais-Biokraftstoffen hat«, sagt Smart.“","reference":"Jennifer Collins: Ist Hanf wirklich eine Wunderpflanze?. In: Deutsche Welle. 3. Oktober 2019 (URL, abgerufen am 18. November 2022) ."},{"text":"„Eine von Barrons Firma Deep Green Metals in Auftrag gegebene vergleichende Ökobilanz (LCA) mit dem Titel \"Woher sollten die Metalle für die grüne Wende kommen?\" wurde im April 2020 veröffentlicht. Das Ergebnis der Ökobilanz ist ein klarer Sieg für die Manganknollen vom Meeresboden.“","reference":"Nils Zimmermann: Elektromobilität – Rohstoffe fürs E-Auto vom Meeresboden. In: Deutsche Welle. 1. Juni 2020 (URL, abgerufen am 18. November 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Ökobilanz","id":"90cb45c79ab524"},"00f6-006b:ce3354eec9989c":{"word":"Ökotonne","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Öko·ton·ne","de-DE":"Öko·ton·ne"},"forms":[{"form":"Ökotonne","tags":["Nominativ","Singular"]},{"form":"Ökotonnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Abfalltonne für biologisch-abbaubare Abfälle, die im Haushalt anfallen"}],"synonyms":[],"origins":["Determinativkompositum aus dem gebundenen Lexem Öko- (von altgriechisch οἶκος (oikos^☆) ^(→ grc) „Haus, Hof, Hauswirtschaft“) und dem Substantiv Tonne"],"examples":[{"text":"„Als Renner erweist sich derzeit die Biotonne. Deren besondere Qualitäten liegen darin, dass sie nicht nur das ökologische Gewissen beruhigt. Sie entlastet auch die Haushaltskasse. Denn für die Biomülltonne muss keine Müllgebühr gezahlt werden. Und je mehr in der Ökotonne verschwindet, desto kleiner und günstiger kann die kostenpflichtige Restmülltonne ausfallen.“","reference":"Gesa Fritz: Der Boom der Biotonnen. In: Frankfurter Rundschau. 26. Juni 2010, abgerufen am 16. April 2023."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökotonne","id":"ce3354eec9989c"},"00f6-006b:41d04f7a37e74e":{"word":"Ökohotel","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Öko·ho·tel","de-DE":"Öko·ho·tel"},"forms":[{"form":"Ökohotel","tags":["Nominativ","Singular"]},{"form":"Ökohotels","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Hotel, das besonders auf Nachhaltigkeit achtet und dabei Umwelt, Energieverbrauch und natürliche Ressourcen möglichst schonend behandelt"}],"synonyms":[],"origins":[],"examples":[{"text":"Unser Ökohotel achtet darauf, möglichst wenig Energie und Wasser zu verbrauchen und regionale Produkte anzubieten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Ökohotel","id":"41d04f7a37e74e"}};
